const M:i64=3604480;const SCALES:[i64;6]=[1016, 1012, 999, 1009, 994, 971];struct Basis{rows:[[i64;48];48],dual:[[f64;8];48],mu:[[f64;48];48],norms:[f64;48]}
fn norm(a:i64,b:i64)->i64{a*a+a*b+b*b}
fn cost(v:&[i64;48],_:&Basis)->i64{(0..6).map(|d|SCALES[d]*SCALES[d]*(0..4).map(|j|norm(v[8*d+j],v[8*d+j+4])).sum::<i64>()).sum()}
struct Search<'a> {
    b: &'a Basis,
    target: [i64; 48],
    projection: [f64; 48],
    k: [i64; 48],
    best: [i64; 48],
    bound: f64,
    nodes: usize,
    limit: usize,
}
impl Search<'_> {
    fn residual(&self) -> [i64; 48] {
        let n = 48;
        let mut r = self.target;
        for i in 0..n {
            for j in 0..n {
                r[j] -= self.k[i] * self.b.rows[i][j];
            }
        }
        r
    }
    fn visit(&mut self, level: isize, partial: f64) {
        if self.nodes >= self.limit {
            return;
        }
        self.nodes += 1;
        if level < 0 {
            let r = self.residual();
            let d = (2 * cost(&r, self.b)) as f64;
            if d < self.bound {
                self.best = r;
                self.bound = d;
            }
            return;
        }
        let i = level as usize;
        let n = 48;
        let center = self.projection[i]
            - (i + 1..n)
                .map(|j| self.k[j] as f64 * self.b.mu[j][i])
                .sum::<f64>();
        let remain = self.bound - partial + 0.25;
        if remain < 0. {
            return;
        }
        let radius = (remain / self.b.norms[i]).sqrt();
        let lo = (center - radius).ceil() as i64;
        let hi = (center + radius).floor() as i64;
        if lo > hi {
            return;
        }
        let z = center.round() as i64;
        let dir = if center - z as f64 >= 0. { 1 } else { -1 };
        let mut visited = 0;
        let count = hi - lo + 1;
        for step in 0..2 * count + 2 {
            let off = if step == 0 {
                0
            } else {
                ((step + 1) / 2) * if step % 2 == 1 { dir } else { -dir }
            };
            let k = z + off;
            if k < lo || k > hi {
                continue;
            }
            visited += 1;
            let delta = center - k as f64;
            let d = partial + delta * delta * self.b.norms[i];
            if d <= self.bound + 0.25 {
                self.k[i] = k;
                self.visit(level - 1, d);
            }
            if visited == count || self.nodes >= self.limit {
                break;
            }
        }
    }
}
fn encode(q:[i64;8], t: &Basis, limit: usize) -> ([i64; 48], usize) {
    let n = 48;
    let mut target = [0i64; 48];
    target[..8].copy_from_slice(&q);
    let projection = std::array::from_fn(|i| (0..8).map(|j|q[j]as f64*t.dual[i][j]).sum::<f64>());
    let mut s = Search {
        b: t,
        target,
        projection,
        k: [0; 48],
        best: target,
        bound: 0.,
        nodes: 0,
        limit,
    };
    for i in (0..n).rev() {
        let center = s.projection[i] - (i + 1..n).map(|j| s.k[j] as f64 * t.mu[j][i]).sum::<f64>();
        s.k[i] = center.round() as i64;
    }
    s.best = s.residual();
    s.bound = (2 * cost(&s.best, t)) as f64;
    s.visit(n as isize - 1, 0.);
    (s.best, s.nodes)
}


